/* @lc app=leetcode id=1675 lang=kotlin */ class Solution { fun minimumDeviation(nums: IntArray): Int = nums.map { if (it % 2 == 1) it * 2 else it }.let { l -> java.util.PriorityQueue<Int>(compareByDescending<Int> { it }).also { it.addAll(l) }.let { pq -> generateSequence(Triple(l.min(), Int.MAX_VALUE, false)) { (mn, best, done) -> if (done) null else pq.peek().let { mx -> minOf(best, mx - mn).let { b -> if (mx % 2 == 1) Triple(mn, b, true) else pq.poll().let { pq.add(mx / 2) }.let { Triple(minOf(mn, mx / 2), b, false) } } } }.last().second } } }